"""Reviewed, parallel English/Arabic narrative. Technical names remain identifiers."""

def block(h_en, h_ar, en, ar):
    return {"heading": {"en": h_en, "ar": h_ar}, "en": en, "ar": ar}


def page(section, en, ar, *blocks, diagram=None):
    p = {"section": section, "title": {"en": en, "ar": ar}, "blocks": list(blocks)}
    if diagram:
        p["diagram"] = diagram
    return p


